CustomField.formula:
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__TotalCPCColorLineItems__c > 0 ,
     TSGCFG__SumofCPCColor__c/  TSGCFG__TotalCPCColorLineItems__c, 
     IF(ABS( TSGCFG__TotalColorVolume__c - TSGCFG__Total_Volume_Includes_Color__c)<>0, TSGCFG__TotalColorMonthlyCost__c / ABS( TSGCFG__TotalColorVolume__c - TSGCFG__Total_Volume_Includes_Color__c) ,
         IF( TSGCFG__TotalCPCColorLineItems__c > 0, TSGCFG__SumofCPCColor__c/  TSGCFG__TotalCPCColorLineItems__c, 0
           )
       )
   )


/* OLD NOT in USE 
IF(ISPICKVAL( TSGCFG__Consolidation_Method__c , 'Average') && TSGCFG__TotalCPCColorLineItems__c > 0 ,
     TSGCFG__SumofCPCColor__c/  TSGCFG__TotalCPCColorLineItems__c, 
     IF(TSGCFG__TotalColorVolume__c<>0, (TSGCFG__TotalColorMonthlyCost__c + TSGCFG__TotalColorMonthlyCostVolumeIncludes__c) /  TSGCFG__TotalColorVolume__c,
         IF( TSGCFG__TotalCPCColorLineItems__c > 0, TSGCFG__SumofCPCColor__c/  TSGCFG__TotalCPCColorLineItems__c, 0
           )
       )
   )*/
